def tokenize_expr(s):
    tokens, num = [], ''
    for c in s:
        if c.isdigit():
            num += c
        else:
            if num:
                tokens.append(num); num = ''
            if c in '+-*/()':
                tokens.append(c)
    if num:
        tokens.append(num)
    return tokens
